import { normalizeMapId, parseGetPosCommand, radarToWorldCoords } from './coordinateEngine'

/**
 * Precomputed 100x100 playable pixel masks per map/floor (1,250 bytes = 10,000 bits, base64-encoded).
 * Derived directly from each calibrated 1024x1024 radar PNG with SimpleRadar logo corners and
 * dimmed upper-floor ghost overlays excluded.
 */
const MAP_PLAYABLE_MASKS_B64: Record<string, string> = {
  mirage:
    '',
  dust2:
    '',
  inferno:
    '',
  nuke_upper:
    '',
  nuke_lower:
    '',
  ancient:
    '',
  anubis:
    '',
  vertigo_upper:
    '',
  vertigo_lower:
    '',
  overpass:
    '',
  train:
    '',
  cache:
    '',
  cobblestone:
    ''
}

const MAP_CODE_BY_ID: Record<string, string> = {
  mirage: 'de_mirage',
  dust2: 'de_dust2',
  inferno: 'de_inferno',
  nuke: 'de_nuke',
  ancient: 'de_ancient',
  anubis: 'de_anubis',
  vertigo: 'de_vertigo',
  overpass: 'de_overpass',
  train: 'de_train',
  cache: 'de_cache',
  cobblestone: 'de_cbble',
  office: 'cs_office',
  italy: 'cs_italy'
}

const DEFAULT_Z_BY_MAP: Record<string, number> = {
  mirage: -160,
  dust2: 0,
  inferno: 128,
  nuke: -380,
  ancient: 100,
  anubis: 50,
  vertigo: 11750,
  overpass: 250,
  train: 0,
  cache: 0,
  cobblestone: 0,
  office: 0,
  italy: 0
}

const decodedMaskCache = new Map<string, Uint8Array>()

function decodeBase64ToBytes(b64: string): Uint8Array {
  if (typeof globalThis.atob === 'function') {
    const bin = globalThis.atob(b64)
    const bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) {
      bytes[i] = bin.charCodeAt(i)
    }
    return bytes
  }
  const nodeBuf = (globalThis as unknown as { Buffer?: { from(s: string, enc: string): Uint8Array } }).Buffer
  if (nodeBuf) {
    return new Uint8Array(nodeBuf.from(b64, 'base64'))
  }
  return new Uint8Array(0)
}

function getMaskBytes(maskKey: string): Uint8Array | null {
  const cached = decodedMaskCache.get(maskKey)
  if (cached) return cached
  const b64 = MAP_PLAYABLE_MASKS_B64[maskKey]
  if (!b64) return null
  const bytes = decodeBase64ToBytes(b64)
  if (bytes.length < 1250) return null
  decodedMaskCache.set(maskKey, bytes)
  return bytes
}

function isMaskCellBitSet(mask: Uint8Array, cx: number, cy: number): boolean {
  if (cx < 0 || cx >= 100 || cy < 0 || cy >= 100) return false
  const idx = cy * 100 + cx
  return ((mask[idx >> 3] ?? 0) & (1 << (idx & 7))) !== 0
}

function resolveMaskKeys(mapId: string, floor?: 'upper' | 'lower'): string[] {
  const norm = normalizeMapId(mapId || '')
  if (norm === 'nuke' || norm === 'vertigo') {
    if (floor === 'lower') return [`${norm}_lower`]
    if (floor === 'upper') return [`${norm}_upper`]
    return [`${norm}_upper`, `${norm}_lower`]
  }
  return [norm]
}

function checkMaskWithTolerance(mask: Uint8Array, cx: number, cy: number): boolean {
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (isMaskCellBitSet(mask, cx + dx, cy + dy)) return true
    }
  }
  return false
}

/**
 * Checks whether a normalized radar percentage point (0-100%) lies inside the playable map
 * boundaries for the specified map (and floor on multi-level maps like Nuke and Vertigo).
 * Enforces a [4, 96] outer safety margin and uses 1-cell neighborhood tolerance so standing spots
 * hugging walls remain valid while open exterior/interior void returns false.
 */
export function isPointInMapBounds(
  mapId: string,
  point: { x: number; y: number },
  floor?: 'upper' | 'lower'
): boolean {
  if (!point || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return false
  if (point.x < 4 || point.x > 96 || point.y < 4 || point.y > 96) return false

  const keys = resolveMaskKeys(mapId, floor)
  const masks = keys.map(getMaskBytes).filter((m): m is Uint8Array => m !== null)
  if (masks.length === 0) {
    // Unknown or user-uploaded custom map fallback: safe [4, 96] margin
    return true
  }

  const cx = Math.min(99, Math.max(0, Math.floor(point.x)))
  const cy = Math.min(99, Math.max(0, Math.floor(point.y)))
  return masks.some((mask) => checkMaskWithTolerance(mask, cx, cy))
}

/**
 * Validates a radar coordinate and snaps out-of-bounds clicks to the nearest playable cell
 * inside the map texture so custom lineups and callouts can never be saved in void space.
 */
export function snapPointToMapBounds(
  mapId: string,
  point: { x: number; y: number },
  floor?: 'upper' | 'lower'
): { x: number; y: number; wasOutOfBounds: boolean } {
  const safeX = Number.isFinite(point?.x) ? point.x : 50
  const safeY = Number.isFinite(point?.y) ? point.y : 50

  if (isPointInMapBounds(mapId, { x: safeX, y: safeY }, floor)) {
    return {
      x: Number(safeX.toFixed(2)),
      y: Number(safeY.toFixed(2)),
      wasOutOfBounds: false
    }
  }

  const clampedX = Math.min(96, Math.max(4, safeX))
  const clampedY = Math.min(96, Math.max(4, safeY))

  const keys = resolveMaskKeys(mapId, floor)
  const masks = keys.map(getMaskBytes).filter((m): m is Uint8Array => m !== null)
  if (masks.length === 0) {
    return {
      x: Number(clampedX.toFixed(2)),
      y: Number(clampedY.toFixed(2)),
      wasOutOfBounds: true
    }
  }

  let bestDistSq = Infinity
  let bestX = clampedX
  let bestY = clampedY

  for (const mask of masks) {
    for (let cy = 4; cy <= 95; cy++) {
      for (let cx = 4; cx <= 95; cx++) {
        if (!isMaskCellBitSet(mask, cx, cy)) continue
        const px = cx + 0.5
        const py = cy + 0.5
        const dSq = (px - clampedX) * (px - clampedX) + (py - clampedY) * (py - clampedY)
        if (dSq < bestDistSq) {
          bestDistSq = dSq
          bestX = px
          bestY = py
        }
      }
    }
  }

  return {
    x: Number(Math.min(96, Math.max(4, bestX)).toFixed(2)),
    y: Number(Math.min(96, Math.max(4, bestY)).toFixed(2)),
    wasOutOfBounds: true
  }
}

/**
 * Generates a CS2 console command to switch to the specified map and optionally apply
 * standard grenade practice server settings.
 */
export function getMapSwitchConsoleCommand(mapId: string, practiceMode = true): string {
  const raw = (mapId || 'mirage').trim().toLowerCase()
  const norm = normalizeMapId(raw)
  const mapCode =
    MAP_CODE_BY_ID[norm] ??
    (raw.startsWith('de_') || raw.startsWith('cs_') ? raw : `de_${norm || 'mirage'}`)

  const baseCmd = `map ${mapCode}`
  if (!practiceMode) return baseCmd

  return `${baseCmd}; sv_cheats 1; bot_kick; mp_warmup_end; mp_freezetime 0; mp_roundtime_defuse 60; sv_infinite_ammo 1; ammo_grenade_limit_total 6; sv_grenade_trajectory_prac_pipreview 1`
}

function getGrenadeWeaponClass(grenadeType: string): string {
  switch ((grenadeType || '').toLowerCase()) {
    case 'flash':
    case 'flashbang':
      return 'weapon_flashbang'
    case 'molotov':
    case 'incendiary':
      return 'weapon_molotov'
    case 'he':
    case 'hegrenade':
      return 'weapon_hegrenade'
    case 'decoy':
      return 'weapon_decoy'
    default:
      return 'weapon_smokegrenade'
  }
}

/**
 * Builds a single-line CS2 practice console command that teleports the player directly to a
 * lineup's standing spot, sets the exact view angle, equips the grenade, and selects slot4.
 */
export function getLineupSetupConsoleCommand(lineup: {
  mapId: string
  title: string
  grenadeType: string
  throwType?: string
  movementType?: string
  originCoords: { x: number; y: number }
  cs2Pos?: { x: number; y: number; z: number; pitch?: number; yaw?: number }
  consoleCommand?: string
}): string {
  const norm = normalizeMapId(lineup.mapId || 'mirage')
  const floorHint = (lineup as { radarFloor?: 'upper' | 'lower' }).radarFloor
  let defaultZ = DEFAULT_Z_BY_MAP[norm] ?? 0
  if (norm === 'nuke' && floorHint === 'lower') defaultZ = -640
  if (norm === 'vertigo' && floorHint === 'lower') defaultZ = 11520

  const parsed = lineup.consoleCommand ? parseGetPosCommand(lineup.consoleCommand) : null

  let x: number
  let y: number
  let z: number
  let pitch: number
  let yaw: number

  if (parsed) {
    x = parsed.x
    y = parsed.y
    z = parsed.z
    pitch = parsed.pitch
    yaw = parsed.yaw
  } else if (
    lineup.cs2Pos &&
    Number.isFinite(lineup.cs2Pos.x) &&
    Number.isFinite(lineup.cs2Pos.y)
  ) {
    x = lineup.cs2Pos.x
    y = lineup.cs2Pos.y
    z = Number.isFinite(lineup.cs2Pos.z) ? lineup.cs2Pos.z : defaultZ
    pitch = Number.isFinite(lineup.cs2Pos.pitch) ? Number(lineup.cs2Pos.pitch) : 0
    yaw = Number.isFinite(lineup.cs2Pos.yaw) ? Number(lineup.cs2Pos.yaw) : 0
  } else {
    const world = radarToWorldCoords(norm, lineup.originCoords, defaultZ)
    x = world.x
    y = world.y
    z = world.z
    pitch = 0
    yaw = 0
  }

  const weapon = getGrenadeWeaponClass(lineup.grenadeType)
  return `setpos_exact ${x.toFixed(2)} ${y.toFixed(2)} ${z.toFixed(2)}; setang ${pitch.toFixed(2)} ${yaw.toFixed(2)} 0; give ${weapon}; slot4`
}

/**
 * Returns a 10,000-byte (100x100) binary playable grid for the specified map & floor
 * where 1 = playable radar pixel and 0 = wall / void.
 */
export function getPlayableMaskGrid(
  mapId: string,
  floor?: 'upper' | 'lower'
): Uint8Array | null {
  const keys = resolveMaskKeys(mapId, floor)
  const masks = keys.map(getMaskBytes).filter((m): m is Uint8Array => m !== null)
  if (masks.length === 0) return null

  const grid = new Uint8Array(10000)
  for (const mask of masks) {
    for (let cy = 0; cy < 100; cy++) {
      for (let cx = 0; cx < 100; cx++) {
        if (isMaskCellBitSet(mask, cx, cy)) {
          grid[cy * 100 + cx] = 1
        }
      }
    }
  }
  return grid
}
